styles:
.page-case .case-hero { padding-top: clamp(150px, 20vh, 240px); padding-bottom: clamp(30px, 5vw, 60px); }
.page-case .case-hero__eyebrow { display: flex; flex-wrap: wrap; gap: 10px 14px; align-items: center; margin-bottom: clamp(18px, 3vw, 32px); }
.page-case .case-hero__eyebrow .tag { font-size: clamp(14px, 1.05vw, 17px); color: var(--red); }
.page-case .case-hero__eyebrow .dot { width: 5px; height: 5px; border-radius: 50%; background: var(--grey-300); }
.page-case .case-hero__title { font-size: clamp(44px, 8.4vw, 132px); line-height: 1.05; color: var(--grey-700); letter-spacing: -0.01em; max-width: 16ch; }
.page-case .case-meta { display: flex; flex-wrap: wrap; gap: clamp(24px, 4vw, 64px); margin-top: clamp(28px, 4vw, 52px); }
.page-case .case-meta__item { display: flex; flex-direction: column; gap: 6px; }
.page-case .case-meta__label { font-size: 13px; letter-spacing: .12em; text-transform: uppercase; color: var(--grey-500); }
.page-case .case-meta__val { font-family: var(--font-display); font-size: clamp(18px, 1.5vw, 22px); color: var(--grey-900); }
.page-case .case-lead { max-width: 60ch; margin-top: clamp(30px, 4vw, 52px); font-size: clamp(18px, 1.4vw, 22px); color: var(--grey-700); }

.page-case .case-cover { border-radius: var(--radius-lg); overflow: hidden; background: var(--bg-alt); }
.page-case .case-cover img { width: 100%; height: clamp(280px, 52vw, 760px); object-fit: cover; }

.page-case .case-prose { max-width: 900px; }
.page-case .case-block { margin-bottom: clamp(40px, 5vw, 72px); }
.page-case .case-block:last-child { margin-bottom: 0; }
.page-case .case-block h2 { font-size: clamp(30px, 3.6vw, 52px); color: var(--red); margin-bottom: clamp(16px, 1.8vw, 26px); }
.page-case .case-block p { color: var(--grey-700); font-size: clamp(16px, 1.15vw, 19px); margin-bottom: 16px; }
.page-case .case-block p:last-child { margin-bottom: 0; }
.page-case .case-steps { display: grid; gap: clamp(16px, 2vw, 24px); }
.page-case .case-step { border: 1px solid var(--line); border-radius: var(--radius); padding: clamp(20px, 2.2vw, 32px); transition: box-shadow .4s var(--ease), transform .4s var(--ease); }
.page-case .case-step:hover { box-shadow: 0 18px 44px rgba(0,0,0,.06); transform: translateY(-3px); }
.page-case .case-step h3 { font-size: clamp(19px, 1.7vw, 24px); color: var(--grey-900); margin-bottom: 8px; }
.page-case .case-step p { margin: 0; font-size: clamp(15px, 1.05vw, 17px); }
.page-case .case-step .num { font-family: var(--font-display); color: var(--red); font-size: clamp(20px, 1.7vw, 24px); margin-right: 10px; }

.page-case .case-band { border-radius: var(--radius-lg); overflow: hidden; }
.page-case .case-band img { width: 100%; height: clamp(220px, 40vw, 520px); object-fit: cover; }

.page-case .case-back { display: inline-flex; align-items: center; gap: 12px; font-family: var(--font-display); font-size: clamp(18px, 1.6vw, 24px); color: var(--grey-900); transition: color .25s var(--ease); }
.page-case .case-back:hover { color: var(--red); }
.page-case .case-back .arrow { width: 42px; height: 42px; border-radius: 50%; border: 1.5px solid var(--red); color: var(--red); display: grid; place-items: center; transition: background .3s var(--ease), color .3s var(--ease); }
.page-case .case-back:hover .arrow { background: var(--red); color: #fff; }

@media (max-width: 760px) {
  .page-case .case-cover img { height: clamp(240px, 60vw, 400px); }
}
